function getWeightedNumber() {
  const rand = Math.random();
  if (rand &lt; 0.10) {
    return Math.floor(Math.random() * 9) + 1;       // 1 to 9 (10% chance)
  } else if (rand &lt; 0.55) {
    return Math.floor(Math.random() * 90) + 10;     // 10 to 99 (45% chance)
  } else {
    return Math.floor(Math.random() * 900) + 100;    // 100 to 999 (45% chance)
  }
}

num1 = getWeightedNumber()
num2 = getWeightedNumber()
sum = num1 + num2

// Create a custom interactive form wrapper element
viewof submission = {
  const form = document.createElement("div");
  form.className = "addition-card";

  form.innerHTML = `
    &lt;div&gt;Calculate the sum: &lt;strong&gt;${num1.toLocaleString()} +${num2.toLocaleString()}&lt;/strong&gt;&lt;/div&gt;
    &lt;div style="display: flex; flex-direction: column; gap: 5px;"&gt;
      &lt;label style="font-size: 0.9rem; font-weight: 500;"&gt;Your Answer:&lt;/label&gt;
      &lt;input type="text" placeholder="Enter total..." autocomplete="off" /&gt;
    &lt;/div&gt;
    &lt;div class="button-group"&gt;
      &lt;button type="button" class="submit-btn"&gt;Submit&lt;/button&gt;
      &lt;button type="button" class="refresh-btn"&gt;Refresh for another&lt;/button&gt;
    &lt;/div&gt;
  `;

  const inputEl = form.querySelector("input");
  const submitBtnEl = form.querySelector(".submit-btn");
  const refreshBtnEl = form.querySelector(".refresh-btn");

  // Initial state
  form.value = { answer: null, count: 0 };

  let submitCount = 0;

  const triggerSubmit = () =&gt; {
    let val = inputEl.value;
    if (!val || val.trim() === "") return;

    submitCount++;
    form.value = { 
      answer: val.trim(), 
      count: submitCount 
    };

    inputEl.value = "";
    inputEl.focus();

    form.dispatchEvent(new CustomEvent("input"));
  };

  submitBtnEl.onclick = triggerSubmit;
  refreshBtnEl.onclick = () =&gt; location.reload();

  inputEl.onkeydown = (e) =&gt; {
    if (e.key === "Enter") {
      e.preventDefault();
      triggerSubmit();
    }
  };

  return form;
}

// Evaluation block
{
  if (!submission || submission.answer === null) {
    return md``;
  }

  let parsed = parseInt(submission.answer.replace(/,/g, ''));

  if (parsed === sum) {
    return md`&lt;span style="color: #2e7d32; font-weight: bold;"&gt;✓ Correct! Excellent work.&lt;/span&gt;`;
  } else {
    return md`&lt;span style="color: #c62828; font-weight: bold;"&gt;✗ Not quite right. Give it another try!&lt;/span&gt;`;
  }
}

function getWeightedNumber() {
  const rand = Math.random();
  if (rand &lt; 0.10) {
    return Math.floor(Math.random() * 9) + 1;       // 1 to 9 (10% chance)
  } else if (rand &lt; 0.55) {
    return Math.floor(Math.random() * 90) + 10;     // 10 to 99 (45% chance)
  } else {
    return Math.floor(Math.random() * 900) + 100;    // 100 to 999 (45% chance)
  }
}

// Generate valid numbers with maxQ properly scoped
_gen = {
  let d, q, div, maxQ;
  do {
    d = getWeightedNumber();
    maxQ = Math.floor(999 / d);
    if (maxQ &lt; 2) maxQ = 2; // Ensure we have room for quotients &gt; 1 if possible

    // Pick quotient starting from 2 up to maxQ (falling back to 1 only if maxQ is 1)
    let minQ = (maxQ &gt; 1) ? 2 : 1;
    q = Math.floor(Math.random() * (maxQ - minQ + 1)) + minQ;

    div = d * q;
  } while (div &gt; 999 || (q === 1 && maxQ &gt; 1));

  return { divisor: d, quotient: q, dividend: div };
}

divisor = _gen.divisor
quotient = _gen.quotient
dividend = _gen.dividend

